    <div class="container">
        <div class="header">
            <h1>Penetration Test Report</h1>
            <div class="subtitle">Security Assessment and Vulnerability Analysis</div>
        </div>

        <div class="meta-info">
            <table>
                <tr>
                    <td>Target Scope:</td>
                    <td>192.168.56.101/32</td>
                </tr>
